/// `pendingApproval` — awaiting the approvals the VTA's policy requires; nothing is
/// published. `staged` — successor published, not yet used; predecessor still active.
/// `overlapping` — successor active, predecessor `retiring`. `completed` — every
/// predecessor retired (or, for `compromise`, `addition` and `migration`, the entry is
/// published and any overlap it began has ended). `aborted` — the successor was
/// retired instead of the predecessor, which stayed or returned to `active`. `expired`
/// — approvals were not gathered before the preview expired; nothing was published.
///
/// An extension type rather than an enum: a value from a newer MINOR of this
/// specification must not crash the parse (SPEC §5.2), and an enum would throw on one.
/// Compare against the constants below, and treat anything else as unrecognised.
extension type const RotationState(String value) {
  static const RotationState pendingApproval = RotationState('pendingApproval');
  static const RotationState staged = RotationState('staged');
  static const RotationState overlapping = RotationState('overlapping');
  static const RotationState completed = RotationState('completed');
  static const RotationState aborted = RotationState('aborted');
  static const RotationState expired = RotationState('expired');

  /// Every value this specification's schema permits.
  static const List<RotationState> values = <RotationState>[
    pendingApproval,
    staged,
    overlapping,
    completed,
    aborted,
    expired
  ];
}

/// Approval progress of a change the VTA's policy gates on more than one approval
/// (CONVENTIONS.md §3.3).
class KeyRoleApprovalState {
  const KeyRoleApprovalState({
    required this.required,
    required this.received,
    this.approvers,
    required this.expiresAt,
  });

  /// Read this payload from a decoded JSON object.
  factory KeyRoleApprovalState.fromJson(Map<String, dynamic> json) =>
      KeyRoleApprovalState(
        required: json['required'] as int,
        received: json['received'] as int,
        approvers: json['approvers'] == null
            ? null
            : (json['approvers'] as List<dynamic>)
                .map((e) => e as String)
                .toList(),
        expiresAt: json['expiresAt'] as String,
      );

  /// Distinct approvals the VTA's policy requires.
  final int required;

  /// Distinct approvals recorded so far, including the initiator's own.
  final int received;

  /// VIDs whose approvals were recorded. Custody projection only; omitted from a
  /// response to anyone who is not themselves an eligible approver of this change.
  final List<String>? approvers;

  /// When the preview, and every approval bound to it, stops being usable.
  final String expiresAt;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'required': required,
        'received': received,
        if (approvers != null) 'approvers': approvers!,
        'expiresAt': expiresAt,
      };
}

/// One change to a role's key set, from preview to completion. The rotation history of
/// a DID is the list of these; the log is the authority for what was published, and
/// this record adds what the log cannot say — which change was which, and (custody
/// projection only) who asked, who approved, and why.
class RotationRecord {
  const RotationRecord({
    required this.rotationId,
    required this.role,
    required this.kind,
    required this.state,
    this.predecessors,
    this.successors,
    this.startedInVersionId,
    this.endedInVersionId,
    this.startedAt,
    this.overlapUntil,
    this.autoRetire,
    this.endedAt,
    this.initiatedBy,
    this.approvals,
    this.reason,
    this.ext,
    this.activatesAt,
    this.gracePeriodEnd,
  });

  /// Read this payload from a decoded JSON object.
  factory RotationRecord.fromJson(Map<String, dynamic> json) => RotationRecord(
        rotationId: json['rotationId'] as String,
        role: KeyRole(json['role'] as String),
        kind: RotationKind(json['kind'] as String),
        state: RotationState(json['state'] as String),
        predecessors: json['predecessors'] == null
            ? null
            : (json['predecessors'] as List<dynamic>)
                .map((e) => e as String)
                .toList(),
        successors: json['successors'] == null
            ? null
            : (json['successors'] as List<dynamic>)
                .map((e) => e as String)
                .toList(),
        startedInVersionId: json['startedInVersionId'] as String?,
        endedInVersionId: json['endedInVersionId'] as String?,
        startedAt: json['startedAt'] as String?,
        overlapUntil: json['overlapUntil'] as String?,
        autoRetire: json['autoRetire'] as bool?,
        endedAt: json['endedAt'] as String?,
        initiatedBy: json['initiatedBy'] as String?,
        approvals: json['approvals'] == null
            ? null
            : KeyRoleApprovalState.fromJson(
                json['approvals'] as Map<String, dynamic>),
        reason: json['reason'] as String?,
        ext: json['ext'] as Map<String, dynamic>?,
        activatesAt: json['activatesAt'] as String?,
        gracePeriodEnd: json['gracePeriodEnd'] as String?,
      );

  final String rotationId;
  final KeyRole role;
  final RotationKind kind;
  final RotationState state;

  /// Verification-method identifiers (or, for `update`, public keys) leaving the role.
  final List<String>? predecessors;

  /// Verification-method identifiers (or, for `update`, public keys) entering the role.
  final List<String>? successors;
  final String? startedInVersionId;
  final String? endedInVersionId;
  final String? startedAt;

  /// Custody projection only. End of the overlap window.
  final String? overlapUntil;

  /// Custody projection only. Whether the VTA retires the predecessor itself at
  /// `overlapUntil`.
  final bool? autoRetire;
  final String? endedAt;

  /// Custody projection only. VID of the administrator whose signed request started the
  /// change.
  final String? initiatedBy;

  /// Custody projection only.
  final KeyRoleApprovalState? approvals;

  /// Custody projection only. The operator's stated reason. Never published.
  final String? reason;
  final Ext? ext;

  /// When the successor becomes `active` and the predecessor `retiring`.
  final String? activatesAt;

  /// `migration` only: the end of the grace period stated in the migration entry
  /// (VTI-KEY-143), after which no verifier accepts an attestation artefact under the
  /// legacy key.
  final String? gracePeriodEnd;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'rotationId': rotationId,
        'role': role.value,
        'kind': kind.value,
        'state': state.value,
        if (predecessors != null) 'predecessors': predecessors!,
        if (successors != null) 'successors': successors!,
        if (startedInVersionId != null)
          'startedInVersionId': startedInVersionId!,
        if (endedInVersionId != null) 'endedInVersionId': endedInVersionId!,
        if (startedAt != null) 'startedAt': startedAt!,
        if (overlapUntil != null) 'overlapUntil': overlapUntil!,
        if (autoRetire != null) 'autoRetire': autoRetire!,
        if (endedAt != null) 'endedAt': endedAt!,
        if (initiatedBy != null) 'initiatedBy': initiatedBy!,
        if (approvals != null) 'approvals': approvals!.toJson(),
        if (reason != null) 'reason': reason!,
        if (ext != null) 'ext': ext!,
        if (activatesAt != null) 'activatesAt': activatesAt!,
        if (gracePeriodEnd != null) 'gracePeriodEnd': gracePeriodEnd!,
      };
}

/// What the node must now do that this entry cannot (VTI-KEY-133). Custody data,
/// present for an `attestation` revocation.
class ResponseFollowUp {
  const ResponseFollowUp({
    this.statusListsToResign,
    this.artefactsToReissue,
  });

  /// Read this payload from a decoded JSON object.
  factory ResponseFollowUp.fromJson(Map<String, dynamic> json) =>
      ResponseFollowUp(
        statusListsToResign: json['statusListsToResign'] as int?,
        artefactsToReissue: json['artefactsToReissue'] as int?,
      );

  /// Status lists signed by the revoked key, which the node MUST re-sign at once under a
  /// sound attestation key.
  final int? statusListsToResign;

  /// Attestation artefacts still in force that the VTA's signing record shows the
  /// revoked key signed, which the node MUST re-issue.
  final int? artefactsToReissue;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        if (statusListsToResign != null)
          'statusListsToResign': statusListsToResign!,
        if (artefactsToReissue != null)
          'artefactsToReissue': artefactsToReissue!,
      };
}

/// Success response. Type
/// https://trusttasks.org/spec/vta/webvh/dids/keys/revoke/1.0#response. A refusal is a
/// `trust-task-error` document, never this.
class Response {
  const Response({
    required this.did,
    required this.outcome,
    this.preview,
    this.newVersionId,
    required this.keys,
    this.rotation,
    this.approvals,
    this.serverless,
    this.newLogEntry,
    this.ext,
    this.followUp,
  });

  /// Read this payload from a decoded JSON object.
  factory Response.fromJson(Map<String, dynamic> json) => Response(
        did: json['did'] as String,
        outcome: KeyRoleChangeOutcome(json['outcome'] as String),
        preview: json['preview'] == null
            ? null
            : DidDocumentPreview.fromJson(
                json['preview'] as Map<String, dynamic>),
        newVersionId: json['newVersionId'] as String?,
        keys: (json['keys'] as List<dynamic>)
            .map((e) => RoleKey.fromJson(e as Map<String, dynamic>))
            .toList(),
        rotation: json['rotation'] == null
            ? null
            : RotationRecord.fromJson(json['rotation'] as Map<String, dynamic>),
        approvals: json['approvals'] == null
            ? null
            : KeyRoleApprovalState.fromJson(
                json['approvals'] as Map<String, dynamic>),
        serverless: json['serverless'] as bool?,
        newLogEntry: json['newLogEntry'] as String?,
        ext: json['ext'] as Map<String, dynamic>?,
        followUp: json['followUp'] == null
            ? null
            : ResponseFollowUp.fromJson(
                json['followUp'] as Map<String, dynamic>),
      );

  final String did;
  final KeyRoleChangeOutcome outcome;

  /// Present when `outcome` is `preview` or `pendingApproval`: the plan, and what an
  /// approval is bound to.
  final DidDocumentPreview? preview;

  /// Present when `outcome` is `applied`: the versionId of the appended entry. Pass it
  /// as the next change's `expectedVersionId`.
  final String? newVersionId;

  /// Every key whose state this change sets or would set, after the change.
  final List<RoleKey> keys;
  final RotationRecord? rotation;

  /// Present when `outcome` is `pendingApproval`.
  final KeyRoleApprovalState? approvals;

  /// True when no hosting server holds this DID. The caller must publish `newLogEntry`
  /// itself; until it does, resolvers still see the previous version.
  final bool? serverless;

  /// The appended entry as JSON text. Present when `serverless` is true.
  final String? newLogEntry;
  final Ext? ext;

  /// What the node must now do that this entry cannot (VTI-KEY-133). Custody data,
  /// present for an `attestation` revocation.
  final ResponseFollowUp? followUp;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'did': did,
        'outcome': outcome.value,
        if (preview != null) 'preview': preview!.toJson(),
        if (newVersionId != null) 'newVersionId': newVersionId!,
        'keys': keys.map((e) => e.toJson()).toList(),
        if (rotation != null) 'rotation': rotation!.toJson(),
        if (approvals != null) 'approvals': approvals!.toJson(),
        if (serverless != null) 'serverless': serverless!,
        if (newLogEntry != null) 'newLogEntry': newLogEntry!,
        if (ext != null) 'ext': ext!,
        if (followUp != null) 'followUp': followUp!.toJson(),
      };
}

/// Generate a replacement in the same role, in the same entry. Absent means: replace
/// only if the role would otherwise have no active key, with the revoked key's
/// algorithm. Not permitted for `update`, whose replacement is the committed
/// successor.
class PayloadReplacement {
  const PayloadReplacement({
    this.keyType,
  });

  /// Read this payload from a decoded JSON object.
  factory PayloadReplacement.fromJson(Map<String, dynamic> json) =>
      PayloadReplacement(
        keyType:
            json['keyType'] == null ? null : KeyType(json['keyType'] as String),
      );

  final KeyType? keyType;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        if (keyType != null) 'keyType': keyType!.value,
      };
}

/// Revoke a did:webvh key for compromise: withdraw it from its role in one entry,
/// without overlap, record the compromise time so verifiers judge its past signatures
/// accordingly, and put a generated replacement in its place where the role would
/// otherwise be empty.
class Payload {
  const Payload({
    required this.did,
    required this.role,
    this.verificationMethod,
    required this.compromisedSince,
    this.replacement,
    this.expectedVersionId,
    this.dryRun,
    this.previewId,
    this.reason,
    this.ext,
  });

  /// Read this payload from a decoded JSON object.
  factory Payload.fromJson(Map<String, dynamic> json) => Payload(
        did: json['did'] as String,
        role: KeyRole(json['role'] as String),
        verificationMethod: json['verificationMethod'] as String?,
        compromisedSince: json['compromisedSince'] as String,
        replacement: json['replacement'] == null
            ? null
            : PayloadReplacement.fromJson(
                json['replacement'] as Map<String, dynamic>),
        expectedVersionId: json['expectedVersionId'] as String?,
        dryRun: json['dryRun'] as bool?,
        previewId: json['previewId'] as String?,
        reason: json['reason'] as String?,
        ext: json['ext'] as Map<String, dynamic>?,
      );

  /// The DID whose keys change.
  final String did;

  /// The role of the compromised key.
  final KeyRole role;

  /// The compromised key's verification method. REQUIRED for every role but `update`,
  /// and forbidden for `update`.
  final String? verificationMethod;

  /// The compromise time (VTI-KEY-121): the earliest instant from which the key is to be
  /// treated as compromised. Err early. Where it cannot be established, give the time
  /// the key was first published — `keys/list` reports it. MUST NOT be later than the
  /// request's `issuedAt`.
  final String compromisedSince;

  /// Generate a replacement in the same role, in the same entry. Absent means: replace
  /// only if the role would otherwise have no active key, with the revoked key's
  /// algorithm. Not permitted for `update`, whose replacement is the committed
  /// successor.
  final PayloadReplacement? replacement;

  /// Optimistic-concurrency precondition: the versionId the caller based this change on
  /// (for example `keys/list`'s `versionId`). The VTA MUST refuse the change with
  /// `vta/webvh/dids:versionConflict` if the DID's latest entry no longer matches.
  final String? expectedVersionId;

  /// Compute and return the preview without writing anything but the plan
  /// (CONVENTIONS.md §3.1). Absent reads as false.
  final bool? dryRun;

  /// Apply exactly the plan a previous dry run of this same request returned. The VTA
  /// MUST apply that plan or nothing, and MUST refuse with `vta/webvh/dids:previewStale`
  /// if it has expired, the log has moved past its base, or this request differs from
  /// the one previewed. An approval (step-up or quorum) is bound to this identifier.
  final String? previewId;

  /// Why the change is being made, for the audit trail and for other approvers. Never
  /// published.
  final String? reason;
  final Ext? ext;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'did': did,
        'role': role.value,
        if (verificationMethod != null)
          'verificationMethod': verificationMethod!,
        'compromisedSince': compromisedSince,
        if (replacement != null) 'replacement': replacement!.toJson(),
        if (expectedVersionId != null) 'expectedVersionId': expectedVersionId!,
        if (dryRun != null) 'dryRun': dryRun!,
        if (previewId != null) 'previewId': previewId!,
        if (reason != null) 'reason': reason!,
        if (ext != null) 'ext': ext!,
      };
}

